CREATE DATABASE IF NOT EXISTS sigma_presensi CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE sigma_presensi;
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, email VARCHAR(255) NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('peserta','staff_presensi','super_admin') NOT NULL, status ENUM('pending','active','inactive','expired') NOT NULL DEFAULT 'pending', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions (id_hash CHAR(64) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, expires_at DATETIME NOT NULL, revoked_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_sessions_user FOREIGN KEY (user_id) REFERENCES users(id), INDEX ix_sessions_user (user_id), INDEX ix_sessions_expiry (expires_at));
